head.script:
// 테스트 설명, 유효성 값 설정
//  - "Body Column 에서만 동작하며 다른 영역의 Column 에 설정 시 무시됩니다." 는 validation 에서 제외 (column 샘플 관례, 설정 영역 con 옵션 미생성)
scwin.tData = {
    "description" : "[column > P > voidNull]<br/>inputType='link' 인 Column 에서 링크('a')의 href 속성에 'javascript:void(null);' 값을 넣을지 설정합니다.",
    "validation" : [
        "true 설정 시, 링크('a')의 href 속성값이 'javascript:void(null);' 로 설정됩니다.",
        "false 설정 시, 링크('a')의 href 속성값이 빈 값('')으로 설정됩니다.",
        "미설정 시, 링크('a')의 href 속성값이 빈 값('')으로 설정됩니다.",
        "voidNull 속성값과 관계없이 Cell 의 링크를 클릭해도 이동하지 않습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (2 = true)
    con_voidNull.setValue("2");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - voidNull 은 렌더 시 결정되므로 con 변경 후 Target 재생성(btn_createTarget -> comp_init) 으로만 반영한다.
//  - 미설정이면 title Column 에 voidNull 속성을 넣지 않는다.
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 (gdl_boolean 은 라벨 '' / 'true' / 'false' 로 분기)
    let cVoidNull = con_voidNull.getText();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[절차] 제목 Column 의 링크 글자 클릭\n[확인] 클릭 후 결과창에 페이지 URL 비교 줄이 자동 출력됨 (줄이 나오지 않고 화면이 다시 로드되면 이동한 것)"', '', 'label1');

    // dataList 생성
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="no" name="no" dataType="text"></w2:column>';
    strDlt += '<w2:column id="title" name="title" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "no" : "1", "title" : "공지사항" },
        { "no" : "2", "title" : "자료실" },
        { "no" : "3", "title" : "자주 묻는 질문" }
    ], false);

    // title Column 속성 (미설정이면 voidNull 속성 제외)
    let attrTitle = ' inputType="link"';
    if (cVoidNull !== "") {
        attrTitle += ' voidNull="' + cVoidNull + '"';
    }

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:500px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="no"></w2:column>';
    strTarget += '<w2:column width="380" style="" inputType="text" id="column2" value="title (link / voidNull ' + (cVoidNull === "" ? "미설정" : cVoidNull) + ')"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="no" value=""></w2:column>';
    strTarget += '<w2:column width="380" style="" id="title" value=""' + attrTitle + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 링크 클릭 감지 (grid render 는 재생성 시 새로 만들어지므로 리스너 중복 없음)
    target1.render.addEventListener("click", scwin.linkClickCheck);
}



// validation 4 판정 출력 : 링크 클릭 후 페이지 URL 이 클릭 전과 같은지 (이동하면 문서가 바뀌어 이 줄이 출력되지 않음)
scwin.linkClickCheck = function (e) {
    let a = e.target.closest ? e.target.closest("a") : null;
    if (!a) {
        return;
    }
    let td = a.closest("td[id*='_cell_']");
    let rowIndex = td ? td.id.split("_cell_")[1].split("_")[0] : "-";
    let href = a.getAttribute("href");
    let beforeUrl = location.href;
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("Row " + rowIndex + " 링크(href '" + href + "') 클릭 후 페이지 URL 클릭 전과 동일 : " + (location.href === beforeUrl));
    }, 300);
}



// validation 1, 2, 3 판정 출력 : 전체 Row 링크 a 의 href 속성값 (속성 자체가 없으면 '속성 없음')
scwin.btn_checkHref_onclick = function () {
    let arr = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        let td = document.querySelector("td[id='" + target1.id + "_cell_" + i + "_1']");
        let a = td ? td.querySelector("a") : null;
        let val = "링크 없음";
        if (a) {
            val = a.hasAttribute("href") ? "'" + a.getAttribute("href") + "'" : "속성 없음";
        }
        arr.push("Row " + i + " " + val);
    }
    wf_body_bottom.getObj("scwin").setReturnValue("href 속성값 : " + arr.join(" / "));
}
